var R_LATM=0.082057; // L·atm/(mol·K)
function ideal(P,V,n,T){
  var miss=0,res={};
  if(P==null){ res.P = n*R_LATM*T/V; }
  else if(V==null){ res.V = n*R_LATM*T/P; }
  else if(n==null){ res.n = P*V/(R_LATM*T); }
  else if(T==null){ res.T = P*V/(n*R_LATM); }
  else { res.P=P;res.V=V;res.n=n;res.T=T; }
  return res;
}
function combined(P1,V1,T1,P2,V2,T2){
  // P1V1/T1 = P2V2/T2 ; 恰好一个为 null
  var vals=[P1,V1,T1,P2,V2,T2];
  var idx=vals.indexOf(null);
  if(idx<0) return {};
  var left=P1*V1/T1, right=P2*V2/T2;
  var res={};
  if(idx===0) res.P1=right*T1/V1;
  else if(idx===1) res.V1=right*T1/P1;
  else if(idx===2) res.T1=P1*V1/right;
  else if(idx===3) res.P2=left*T2/V2;
  else if(idx===4) res.V2=left*T2/P2;
  else if(idx===5) res.T2=P2*V2/left;
  return res;
}
var EXPORTS={ideal:ideal, combined:combined, R_LATM:R_LATM};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.GasLawForgePure = EXPORTS; }
